<script setup lang="ts">
import { getArticle } from '~/data/articles'; import { getRace } from '~/data/races'; import { getRunner } from '~/data/runners'; import { getTrailRoute } from '~/data/routes'
const pageRoute=useRoute(); const article=computed(()=>getArticle(pageRoute.params.slug as string)); if(!article.value) throw createError({statusCode:404,statusMessage:'Članek ni najden'}); useSiteSeo(()=>article.value?.title,()=>article.value?.description,{type:'article',image:()=>article.value?.image,imageAlt:()=>article.value?.title,publishedAt:()=>article.value?.publishedAt,noindex:true})
const related=computed(()=>{ if(!article.value)return []; const list=[]; if(article.value.relatedRace){const v=getRace(article.value.relatedRace);if(v)list.push({label:"Povezana tekma",name:v.name,to:`/races/${v.slug}`})} if(article.value.relatedRunner){const v=getRunner(article.value.relatedRunner);if(v)list.push({label:"Povezan tekač",name:v.name,to:`/runners/${v.slug}`})} if(article.value.relatedRoute){const v=getTrailRoute(article.value.relatedRoute);if(v)list.push({label:"Povezana trasa",name:v.name,to:`/routes/${v.slug}`})} return list})
</script>
<template><article v-if="article" class="story-page"><header class="story-header shell"><p class="eyebrow">{{ article.category }} · {{ new Date(article.publishedAt).toLocaleDateString('sl-SI') }}</p><h1>{{ article.title }}</h1><p>{{ article.subtitle }}</p></header><div class="story-image"><img :src="article.image" :alt="article.title"></div><div class="story-layout shell"><aside></aside><div class="story-body"><p v-for="paragraph in article.body" :key="paragraph">{{ paragraph }}</p><a v-if="article.relatedRunner === 'nejc-ursic'" href="https://utmb.world/runner/2586047.nejc.ursic" target="_blank" rel="noopener noreferrer">UTMB profil Nejca Uršiča ↗</a></div></div><section v-if="related.length" class="related-entities shell"><p class="eyebrow">Povezano</p><NuxtLink v-for="item in related" :key="item.to" :to="item.to"><span>{{ item.label }}</span><strong>{{ item.name }}</strong><em>↗</em></NuxtLink></section></article></template>
